-- Generated by scripts/current-sql.mjs; documentation only.
-- Signature: app.publish_story_entries(p_collection_id uuid, p_expected_entry_revision bigint, p_entry_ids uuid[])
-- Owner: cms_migration_owner
-- ACL: {cms_migration_owner=X/cms_migration_owner,cms_authenticated_user=X/cms_migration_owner}

CREATE OR REPLACE FUNCTION app.publish_story_entries(p_collection_id uuid, p_expected_entry_revision bigint, p_entry_ids uuid[])
 RETURNS TABLE(entry_revision bigint, published_entry_revision bigint, published_count integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE actor uuid; head public.collections%ROWTYPE; schema_head public.collection_schema_versions%ROWTYPE;
        draft_entry record; defect text;
BEGIN
  actor:=app.require_actor();
  PERFORM app.guard_collection_review_publication(p_collection_id);
  IF p_entry_ids IS NULL OR cardinality(p_entry_ids) NOT BETWEEN 1 AND 200
    OR array_position(p_entry_ids,NULL) IS NOT NULL
    OR (SELECT count(DISTINCT id) FROM unnest(p_entry_ids) id)<>cardinality(p_entry_ids) THEN
    RAISE EXCEPTION 'choose between one and 200 distinct stories' USING ERRCODE='CMS04';
  END IF;
  SELECT * INTO head FROM public.collections WHERE id=p_collection_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'collection not found' USING ERRCODE='CMS03'; END IF;
  IF NOT app.can_publish(head.site_id) THEN RAISE EXCEPTION 'not permitted to publish entries for this collection' USING ERRCODE='CMS02'; END IF;
  IF head.entry_revision IS DISTINCT FROM p_expected_entry_revision THEN RAISE EXCEPTION 'stale collection entry revision' USING ERRCODE='CMS01',DETAIL=jsonb_build_object('entry_revision',head.entry_revision)::text; END IF;
  IF head.reader_key IS DISTINCT FROM 'stories' THEN RAISE EXCEPTION 'individual publication is only available for Stories' USING ERRCODE='CMS04';END IF;
  IF (SELECT count(*) FROM public.collection_entries WHERE collection_id=head.id AND id=ANY(p_entry_ids) AND archived_at IS NULL)<>cardinality(p_entry_ids) THEN
    RAISE EXCEPTION 'a selected story is unavailable to this site' USING ERRCODE='CMS03';
  END IF;
  SELECT * INTO schema_head FROM public.collection_schema_versions WHERE id=head.published_schema_version_id AND collection_id=head.id;
  IF NOT FOUND THEN RAISE EXCEPTION 'publish the collection schema before its entries' USING ERRCODE='CMS04'; END IF;
  FOR draft_entry IN
    SELECT entry.id,version.schema_version_id,version."values" FROM public.collection_entries entry
    JOIN public.collection_entry_versions version ON version.id=entry.draft_version_id AND version.entry_id=entry.id
    WHERE entry.collection_id=head.id AND entry.id=ANY(p_entry_ids) AND entry.archived_at IS NULL ORDER BY entry.sort_index
  LOOP
    IF draft_entry.schema_version_id<>schema_head.id AND NOT app.story_controls_schema_compatible(draft_entry.schema_version_id,schema_head.id) THEN RAISE EXCEPTION 'entry drafts must be saved against the published collection schema' USING ERRCODE='CMS04'; END IF;
    defect:=app.collection_entry_values_defect(head.site_id,schema_head.fields,draft_entry."values");
    IF defect IS NOT NULL THEN RAISE EXCEPTION 'entry is not publishable: %',defect USING ERRCODE='CMS04'; END IF;
  END LOOP;
  IF (WITH chosen AS (
    SELECT version.values AS story_values FROM public.collection_entries entry
    JOIN public.collection_entry_versions version ON version.id=CASE WHEN entry.id=ANY(p_entry_ids) THEN entry.draft_version_id ELSE entry.published_version_id END AND version.entry_id=entry.id
    WHERE entry.collection_id=head.id AND CASE WHEN entry.id=ANY(p_entry_ids) THEN entry.archived_at ELSE entry.published_archived_at END IS NULL
   ), featured AS (SELECT story_values->>'newsroom_rank' AS position FROM chosen WHERE jsonb_typeof(story_values->'newsroom_rank')='number' AND story_values->>'newsroom_rank' ~ '^[1-5]$')
   SELECT count(*)>5 OR count(DISTINCT position)<>count(*) FROM featured) THEN
   RAISE EXCEPTION 'Publish the changed Newsroom order together from the site Publish screen. Other featured stories still have draft changes.' USING ERRCODE='CMS04';
  END IF;
  UPDATE public.collection_entries SET published_version_id=draft_version_id,
    published_sort_index=sort_index,published_archived_at=archived_at,revision=revision+1
   WHERE collection_id=head.id AND id=ANY(p_entry_ids);
  SELECT count(*)::integer INTO published_count FROM public.collection_entries
   WHERE collection_id=head.id AND published_version_id IS NOT NULL AND published_archived_at IS NULL;
  entry_revision:=head.entry_revision+1;
  -- These are publication-generation counters, not entry version identities.
  -- Keep the list visibly dirty whenever any other private change remains.
  published_entry_revision:=CASE WHEN EXISTS(SELECT 1 FROM public.collection_entries e
    WHERE e.collection_id=head.id AND (e.draft_version_id IS DISTINCT FROM e.published_version_id
      OR e.sort_index IS DISTINCT FROM e.published_sort_index OR e.archived_at IS DISTINCT FROM e.published_archived_at))
    THEN entry_revision-1 ELSE entry_revision END;
  UPDATE public.collections SET entry_revision=publish_story_entries.entry_revision,
    published_entry_revision=publish_story_entries.published_entry_revision WHERE id=head.id;
  PERFORM app.write_audit(head.site_id,'user',actor,'collection.entries.publish','collection',head.id,NULL,NULL,
    jsonb_build_object('entry_revision',entry_revision,'published_count',published_count,'entry_ids',to_jsonb(p_entry_ids)));
  PERFORM app.emit_outbox(head.site_id,'collection.entries.published',
    jsonb_build_object('collection_id',head.id,'entry_revision',entry_revision,'entry_count',published_count));
  RETURN NEXT;
END
$function$
